-- 物品使用第二批：增强捕捉工具必须把“孵化时前缀概率倍率”随未孵化宠物
-- 持久化。0 是普通100%的显式哨兵，当前万能绳索使用200。
ALTER TABLE char_pets
    ADD COLUMN IF NOT EXISTS hatch_prefix_rate_pct INT NOT NULL DEFAULT 0
        CHECK (hatch_prefix_rate_pct BETWEEN 0 AND 1000);

-- 仅保存已有资料明确列出全部内容的固定礼包；随机箱、概率未知箱和包含当前
-- 物品空间外伪 ID 的礼包不入表。
CREATE TABLE IF NOT EXISTS game_item_use_rewards (
    source_item_id INT NOT NULL CHECK (source_item_id > 0),
    seq            SMALLINT NOT NULL CHECK (seq > 0),
    reward_item_id INT NOT NULL CHECK (reward_item_id > 0),
    quantity       INT NOT NULL CHECK (quantity > 0),
    PRIMARY KEY (source_item_id,seq)
);

INSERT INTO game_item_use_rewards(source_item_id,seq,reward_item_id,quantity) VALUES
    -- 原表脚本与描述同时给出唯一目标和数量的7种道具套装。
    (3278,1,3078,10),(3279,1,3079,10),(3280,1,3080,10),
    (3282,1,3083,5),(3283,1,3084,5),(3284,1,3258,5),(3285,1,3259,5),
    (35599,1,25965,1000),
    (10179,1,3121,1),
    (10445,1,10442,1),(10445,2,26549,2),(10445,3,10465,1),(10445,4,10466,1),
    (10445,5,25031,1),(10445,6,10007,1),(10445,7,12092,1),(10445,8,3329,5),
    (10445,9,12122,30),(10445,10,4477,20),
    (10917,1,10626,1),(10917,2,10890,1),(10917,3,10891,40),
    (11770,1,13898,3),(11770,2,12291,1),
    (14807,1,3121,1),
    (25354,1,25232,5),(25354,2,26186,1),(25354,3,26189,1),
    (35944,1,3121,1),
    (42434,1,42432,1),(42435,1,42433,1),(42578,1,3121,1),(42600,1,10943,1)
ON CONFLICT(source_item_id,seq) DO UPDATE SET
    reward_item_id=EXCLUDED.reward_item_id,quantity=EXCLUDED.quantity;

DO $$
DECLARE n INT;
BEGIN
    SELECT count(DISTINCT source_item_id) INTO n FROM game_item_use_rewards;
    IF n <> 19 THEN RAISE EXCEPTION '固定礼包应为19种，实得%', n; END IF;
    SELECT count(*) INTO n FROM game_item_use_rewards r
     WHERE NOT EXISTS(SELECT 1 FROM game_items i WHERE i.id=r.source_item_id)
        OR NOT EXISTS(SELECT 1 FROM game_items i WHERE i.id=r.reward_item_id)
           AND NOT EXISTS(SELECT 1 FROM game_equipment e WHERE e.id=r.reward_item_id);
    IF n <> 0 THEN RAISE EXCEPTION '固定礼包有%条奖励未命中物品定义', n; END IF;
END $$;

-- 确定性货币道具。copper 按1金=1000银、1银=1000铜规范化；与彩玉互斥。
CREATE TABLE IF NOT EXISTS game_item_currency_rewards (
    item_id INT PRIMARY KEY CHECK (item_id > 0),
    caiyu   BIGINT NOT NULL DEFAULT 0 CHECK (caiyu >= 0),
    copper  BIGINT NOT NULL DEFAULT 0 CHECK (copper >= 0),
    CHECK ((caiyu > 0) <> (copper > 0))
);
INSERT INTO game_item_currency_rewards(item_id,caiyu) VALUES
    (25151,10),(25965,100)
ON CONFLICT(item_id) DO UPDATE SET caiyu=EXCLUDED.caiyu;

-- ov_desc 与同名物品的独立脚本明确给出固定数量；不纳入随机/限期红包。
INSERT INTO game_item_currency_rewards(item_id,caiyu,copper) VALUES
    (3097,0,100000000),(11889,0,10000000),(12317,0,50000000),
    (12330,0,10000),(12501,0,888000),(12575,0,888000),
    (12576,0,8888000),(12577,0,88888000),(12578,0,888888000)
ON CONFLICT(item_id) DO UPDATE SET caiyu=EXCLUDED.caiyu,copper=EXCLUDED.copper;

DO $$
DECLARE n INT;
BEGIN
    SELECT count(*) INTO n FROM game_item_currency_rewards;
    IF n <> 11 THEN RAISE EXCEPTION '货币兑换物品应为11种，实得%', n; END IF;
    SELECT count(*) INTO n FROM game_item_currency_rewards r
     WHERE NOT EXISTS(SELECT 1 FROM game_items i WHERE i.id=r.item_id);
    IF n <> 0 THEN RAISE EXCEPTION '彩玉兑换物品有%件未命中物品定义', n; END IF;
END $$;

-- 宠物幻化书只覆盖显示模型；种族、属性、技能保持原宠物。金甲/银甲书要求
-- 已召唤且未骑乘，普通幻化书允许骑乘时更新坐骑模型。
CREATE TABLE IF NOT EXISTS game_item_pet_transmogs (
    item_id           INT PRIMARY KEY CHECK (item_id > 0),
    target_monster_id INT NOT NULL CHECK (target_monster_id > 0),
    model             INT NOT NULL CHECK (model > 0),
    duration_sec      INT NOT NULL CHECK (duration_sec BETWEEN 1 AND 86400),
    require_unmounted BOOLEAN NOT NULL DEFAULT FALSE
);
