ALTER TABLE char_pets ADD COLUMN IF NOT EXISTS transmog_model INT NOT NULL DEFAULT 0 CHECK (transmog_model >= 0);
ALTER TABLE char_pets ADD COLUMN IF NOT EXISTS transmog_until TIMESTAMPTZ NOT NULL DEFAULT '1970-01-01 00:00:00+00';

DO $$
DECLARE n INT;
BEGIN
    SELECT count(*) INTO n FROM game_item_pet_transmogs;
    IF n <> 47 THEN RAISE EXCEPTION '宠物幻化书应为47件，实得%', n; END IF;
    SELECT count(*) INTO n FROM game_item_pet_transmogs t
     WHERE NOT EXISTS(SELECT 1 FROM game_items i WHERE i.id=t.item_id)
        OR NOT EXISTS(SELECT 1 FROM gamedata.ov_cmon c WHERE c.index=t.target_monster_id);
    IF n <> 0 THEN RAISE EXCEPTION '宠物幻化书有%件未命中物品或目标模型定义', n; END IF;
END $$;

-- 0x1036 装备换形。换形物品的客户端模型映射开发期从现有 suit_fx 资产导入，
-- 正式服务端只读本表；玩家实例只保存已融合的物品 ID。
CREATE TABLE IF NOT EXISTS game_item_avatar_fusions (
    item_id         INT PRIMARY KEY CHECK (item_id > 0),
    appearance_part SMALLINT NOT NULL CHECK (appearance_part BETWEEN 0 AND 5),
    model           INT NOT NULL CHECK (model BETWEEN 0 AND 65535)
);

