ON CONFLICT(item_id) DO UPDATE SET
    appearance_part=EXCLUDED.appearance_part,model=EXCLUDED.model;

DO $$
DECLARE n INT;
BEGIN
    SELECT count(*) INTO n FROM game_item_avatar_fusions;
    IF n <> 5710 THEN RAISE EXCEPTION '可映射装备换形物品应为5710件，实得%', n; END IF;
    SELECT count(*) INTO n FROM game_item_avatar_fusions f
     WHERE NOT EXISTS(SELECT 1 FROM game_items i WHERE i.id=f.item_id)
        OR NOT EXISTS(SELECT 1 FROM gamedata.ov_desc d WHERE d.index=f.item_id AND d.desc_ LIKE '%外形变化为%');
    IF n <> 0 THEN RAISE EXCEPTION '装备换形表有%件未命中授权物品', n; END IF;
END $$;
-- AVATAR_FUSION_VALUES_END

CREATE TABLE IF NOT EXISTS game_item_avatar_fusion_affixes (
    item_id INT NOT NULL REFERENCES game_item_avatar_fusions(item_id) ON DELETE CASCADE,
    seq     SMALLINT NOT NULL CHECK (seq > 0),
    attr_id INT NOT NULL CHECK (attr_id > 0),
    value   INT NOT NULL,
    mode    SMALLINT NOT NULL CHECK (mode IN (0,1)),
    PRIMARY KEY (item_id,seq)
);
