DO $$
DECLARE n INT;
BEGIN
    SELECT count(*) INTO n FROM game_item_avatar_fusion_affixes;
    IF n <> 13696 THEN RAISE EXCEPTION '装备换形属性应为13696条，实得%', n; END IF;
END $$;
-- AVATAR_FUSION_AFFIX_VALUES_END

ALTER TABLE character_items ADD COLUMN IF NOT EXISTS fused_appearance_item_id INT NOT NULL DEFAULT 0 CHECK (fused_appearance_item_id >= 0);
ALTER TABLE character_equips ADD COLUMN IF NOT EXISTS fused_appearance_item_id INT NOT NULL DEFAULT 0 CHECK (fused_appearance_item_id >= 0);
ALTER TABLE character_warehouse_items ADD COLUMN IF NOT EXISTS fused_appearance_item_id INT NOT NULL DEFAULT 0 CHECK (fused_appearance_item_id >= 0);
ALTER TABLE character_stall_items ADD COLUMN IF NOT EXISTS fused_appearance_item_id INT NOT NULL DEFAULT 0 CHECK (fused_appearance_item_id >= 0);
ALTER TABLE character_mail_attachments ADD COLUMN IF NOT EXISTS fused_appearance_item_id INT NOT NULL DEFAULT 0 CHECK (fused_appearance_item_id >= 0);

CREATE TABLE IF NOT EXISTS game_item_experience_boosts (
    item_id          INT PRIMARY KEY CHECK (item_id > 0),
    player_bonus_pct INT NOT NULL DEFAULT 0 CHECK (player_bonus_pct BETWEEN 0 AND 900),
    pet_bonus_pct    INT NOT NULL DEFAULT 0 CHECK (pet_bonus_pct BETWEEN 0 AND 900),
    duration_sec     INT NOT NULL CHECK (duration_sec BETWEEN 1 AND 86400),
    CHECK (player_bonus_pct > 0 OR pet_bonus_pct > 0)
);
INSERT INTO game_item_experience_boosts(item_id,player_bonus_pct,pet_bonus_pct,duration_sec) VALUES
    (10250,0,100,3600),
    (10891,100,100,10800),
    (12394,200,0,3600),
    (25268,0,50,3600),
    (25269,0,100,3600)
ON CONFLICT(item_id) DO UPDATE SET
    player_bonus_pct=EXCLUDED.player_bonus_pct,
    pet_bonus_pct=EXCLUDED.pet_bonus_pct,
    duration_sec=EXCLUDED.duration_sec;

DO $$
DECLARE n INT;
BEGIN
    SELECT count(*) INTO n FROM game_item_experience_boosts;
    IF n <> 5 THEN RAISE EXCEPTION '脚本型经验物品应为5件，实得%', n; END IF;
    SELECT count(*) INTO n FROM game_item_experience_boosts b
     WHERE NOT EXISTS(SELECT 1 FROM game_items i WHERE i.id=b.item_id);
    IF n <> 0 THEN RAISE EXCEPTION '脚本型经验物品有%件未命中物品定义', n; END IF;
END $$;

CREATE TABLE IF NOT EXISTS game_item_title_unlocks (
    item_id INT PRIMARY KEY CHECK (item_id > 0),
    title   TEXT NOT NULL CHECK (char_length(title) BETWEEN 1 AND 64)
);
