DO $$
DECLARE n INT;
BEGIN
    SELECT count(*) INTO n FROM game_item_title_unlocks;
    IF n <> 45 THEN RAISE EXCEPTION '称号石应为45件，实得%', n; END IF;
    SELECT count(*) INTO n FROM game_item_title_unlocks t
     WHERE NOT EXISTS(SELECT 1 FROM game_items i WHERE i.id=t.item_id);
    IF n <> 0 THEN RAISE EXCEPTION '称号石有%件未命中物品定义', n; END IF;
END $$;

-- 鞍具：research/fenfentu/pets.json saddles，名称只规范分隔符后精确匹配。
-- speed 为相对人物基础步速的百分比；模型来自 game_monsters.sprite。
CREATE TABLE game_item_saddles (
    item_id INT PRIMARY KEY REFERENCES game_items(id),
    speed_bonus_bp INT NOT NULL DEFAULT 0 CHECK (speed_bonus_bp >= 0),
    passengers INT NOT NULL DEFAULT 1 CHECK (passengers BETWEEN 1 AND 6),
    combination_model INT NOT NULL DEFAULT 0 CHECK (combination_model >= 0),
    distinct_pets BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE TABLE game_item_saddle_pets (
    item_id INT NOT NULL REFERENCES game_item_saddles(item_id),
    pet_id INT NOT NULL REFERENCES game_pets(id),
    PRIMARY KEY(item_id,pet_id)
);
ALTER TABLE char_pets ADD COLUMN riding_saddle INT NOT NULL DEFAULT 0 CHECK (riding_saddle >= 0);
