-- 宝宝经验珠按当前宠物等级发放固定经验。79 档逐项来自
-- research/fenfentu/pet-exps.json；max_above_owner=4 来自物品原始说明。
CREATE TABLE game_item_pet_experience (
    item_id         INT NOT NULL REFERENCES game_items(id),
    pet_level       INT NOT NULL CHECK (pet_level BETWEEN 1 AND 79),
    experience      BIGINT NOT NULL CHECK (experience > 0),
    max_above_owner INT NOT NULL DEFAULT 4 CHECK (max_above_owner >= 0),
    PRIMARY KEY(item_id,pet_level)
);
