INSERT INTO game_rack_goods(item_id,category_id,price,quantity,flags,remain,part,active) VALUES
 (3633,7,800,1,0,-1,'',TRUE),(3287,7,800,1,0,-1,'',TRUE)
ON CONFLICT(item_id) DO UPDATE SET category_id=EXCLUDED.category_id,price=EXCLUDED.price,quantity=EXCLUDED.quantity,remain=EXCLUDED.remain,active=TRUE;
UPDATE game_item_saddles SET distinct_pets=FALSE WHERE item_id=14895;
-- 高强化保护物：7 级以上才使用保护道具 4478。这是我们的玩法规则，**不是**客户端
-- 原始数据 —— gamedata.ov_refine 是无损客户端投影、只读，规则因此落在业务表，
-- 由 LoadRefineRecipes 与原始列合并取值（业务表没有的等级回退原始值）。
CREATE TABLE IF NOT EXISTS game_refine_protect_items (
    refine_level SMALLINT PRIMARY KEY CHECK (refine_level >= 0),
    protect_item INT NOT NULL DEFAULT 0 CHECK (protect_item >= 0)
);
INSERT INTO game_refine_protect_items(refine_level,protect_item)
SELECT lv, CASE WHEN lv >= 7 THEN 4478 ELSE 0 END FROM generate_series(0,20) AS lv
ON CONFLICT (refine_level) DO UPDATE SET protect_item = EXCLUDED.protect_item;
-- 神奇货架：加工炉（装备精炼）当前所有配方材料及保护材料，统一 1 彩玉且不限量。
-- 直接从 ov_refine 提取，后续原始精炼表增加材料时重新初始化也不会漏项。
INSERT INTO game_rack_categories(id,name,position) VALUES(8,'强化材料',8)
ON CONFLICT(id) DO UPDATE SET name=EXCLUDED.name,position=EXCLUDED.position;
WITH material_ids AS (
    SELECT mat_1id AS item_id FROM gamedata.ov_refine WHERE mat_1id > 0
    UNION
    SELECT mat_2id FROM gamedata.ov_refine WHERE mat_2id > 0
    UNION
    SELECT mat_3id FROM gamedata.ov_refine WHERE mat_3id > 0
    UNION
    SELECT protect_item FROM gamedata.ov_refine WHERE protect_item > 0
)
INSERT INTO game_rack_goods(item_id, category_id, price, quantity, flags, remain, part, active)
SELECT item_id, 8, 1, 1, 0, -1, '', TRUE
  FROM material_ids
ON CONFLICT (item_id) DO UPDATE
  SET category_id = EXCLUDED.category_id,
      price = EXCLUDED.price,
      quantity = EXCLUDED.quantity,
      flags = EXCLUDED.flags,
      remain = EXCLUDED.remain,
      part = EXCLUDED.part,
      active = EXCLUDED.active;
-- 锋刃卡片单卡升阶：成功升一级，失败时材料消失。mat_1 编码为 (数量 << 16) | 物品 ID。
-- 这是我们自己的玩法配方，**不是**客户端原始数据，因此落在业务表，
-- 由 LoadCraftRecipes 与 gamedata.ov_combine 合并（row_no 从 4900 起，不与原始行冲突）。
CREATE TABLE IF NOT EXISTS game_craft_extra_recipes (
    row_no            INT PRIMARY KEY CHECK (row_no > 0),
    product_item_id   INT NOT NULL CHECK (product_item_id > 0),
    cost              BIGINT NOT NULL DEFAULT 0 CHECK (cost >= 0),
    need_lifeskill_id INT NOT NULL DEFAULT 0 CHECK (need_lifeskill_id >= 0),
    prof_need         INT NOT NULL DEFAULT 0,
    prof_max          INT NOT NULL DEFAULT 0,
    prof_gain         INT NOT NULL DEFAULT 0,
    disappear_rate    INT NOT NULL DEFAULT 0 CHECK (disappear_rate BETWEEN 0 AND 100),
    success_rate      INT NOT NULL DEFAULT 0 CHECK (success_rate BETWEEN 0 AND 100),
    skill_level_need  INT NOT NULL DEFAULT 0 CHECK (skill_level_need >= 0),
    mat_count         SMALLINT NOT NULL DEFAULT 0 CHECK (mat_count BETWEEN 0 AND 5),
    mat_1             BIGINT NOT NULL DEFAULT 0,
    mat_2             BIGINT NOT NULL DEFAULT 0,
    mat_3             BIGINT NOT NULL DEFAULT 0,
    mat_4             BIGINT NOT NULL DEFAULT 0,
    mat_5             BIGINT NOT NULL DEFAULT 0,
    out_qty           INT NOT NULL DEFAULT 1 CHECK (out_qty > 0),
    show_type         INT NOT NULL DEFAULT 0 CHECK (show_type BETWEEN 0 AND 255),
    CHECK (success_rate + disappear_rate <= 100)
);
INSERT INTO game_craft_extra_recipes(
    row_no, product_item_id, disappear_rate, success_rate, mat_count, mat_1, out_qty)
VALUES
  (4900, 7685, 15, 85, 1, 73219, 1),
  (4901, 7686, 15, 85, 1, 73220, 1),
