  (4903, 7688, 25, 75, 1, 73222, 1),
  (4904, 7689, 35, 65, 1, 73223, 1),
  (4905, 7690, 35, 65, 1, 73224, 1),
  (4906, 7691, 45, 55, 1, 73225, 1),
  (4907, 7692, 45, 55, 1, 73226, 1),
  (4908, 7693, 55, 45, 1, 73227, 1),
  (4909, 7694, 55, 45, 1, 73228, 1),
  (4910, 7695, 65, 35, 1, 73229, 1),
  (4911, 7696, 65, 35, 1, 73230, 1)
ON CONFLICT (row_no) DO UPDATE SET
  product_item_id = EXCLUDED.product_item_id,
  disappear_rate = EXCLUDED.disappear_rate,
  success_rate = EXCLUDED.success_rate,
  mat_count = EXCLUDED.mat_count,
  mat_1 = EXCLUDED.mat_1,
  out_qty = EXCLUDED.out_qty;
-- 龙城飞空艇仙子云翘(trans_list=1)追加两条野外航线: 华山脚 / 下古岳平原。
-- 落点坐标与野外传送点 NPC(N856_004 / N856_021)一致；
-- destination_index 必须紧跟 0..6(七个城市)连续，客户端菜单按索引顺序展示。
INSERT INTO game_transport_destinations
  (trans_list, destination_index, source_map_id, name, map_id, x, y, price)
VALUES
  (1, 7, 7, '华山脚',     4,  5446, 2797, 0),
  (1, 8, 7, '下古岳平原', 21, 9201, 1953, 0)
ON CONFLICT (trans_list, destination_index) DO UPDATE SET
  source_map_id = EXCLUDED.source_map_id,
  name = EXCLUDED.name,
  map_id = EXCLUDED.map_id,
  x = EXCLUDED.x,
  y = EXCLUDED.y,
  price = EXCLUDED.price;
